-- La migración se aplica dos veces antes de estas comprobaciones.
select test.check((select count(*) = 3 from public.families), 'Repeat migration preserves families');
select test.check((select count(*) = 4 from public.profiles), 'Repeat migration preserves users');
select test.check((select not public and file_size_limit = 5242880
  and allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp'] from storage.buckets where id = 'payment-qr'), 'Private QR bucket with image limits');
select test.check((select count(*) = 4 from pg_policies where schemaname = 'storage' and policyname like 'casa_payment_qr_%'), 'Four idempotent storage policies');
set role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000001', false);
select test.check(public.casa_is_sysadmin(), 'Admin helper works through profile RLS');
select public.casa_admin_rename_family(1, '  Familia García  ');
select test.check((select name = 'Familia García' from public.families where id = 1), 'Rename trims and persists');
select test.expect_error($q$select public.casa_admin_rename_family(2, 'familia garcía')$q$, '22023');
select test.expect_error($q$select public.casa_admin_rename_family(1, '  ')$q$, '22023');
select test.expect_error($q$select public.casa_admin_rename_family(1, repeat('a', 81))$q$, '22023');
select test.expect_error($q$select public.casa_admin_rename_family(1, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_rename_family(999, 'Falta')$q$, '22023');
select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000002', 3, null);
select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000003', 2, 3);
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000002', 3, 2)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000003', 2, 2)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000003', 2, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000003', 2, 999)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000002', null, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000002', 999, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000004', 1, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-000000000001', 1, null)$q$, '22023');
select test.expect_error($q$select public.casa_admin_assign_user_families('00000000-0000-0000-0000-999999999999', 1, null)$q$, '22023');
insert into storage.objects (bucket_id, name) values ('payment-qr', 'qr/code.png');
select test.check((select count(*) = 1 from storage.objects), 'Admin writes QR but cannot read receipts with QR policy');
update storage.objects set name = 'qr/updated.png' where bucket_id = 'payment-qr';
select test.check((select name = 'qr/updated.png' from storage.objects where bucket_id = 'payment-qr'), 'Admin replaces QR');
select test.expect_error($q$insert into storage.objects (bucket_id, name) values ('payment-qr', 'outside.png')$q$, '42501');
select test.expect_error($q$update storage.objects set bucket_id = 'receipts' where bucket_id = 'payment-qr'$q$, '42501');
select test.expect_error($q$insert into storage.objects (bucket_id, name) values ('receipts', 'qr/private.png')$q$, '42501');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000002', false);
select test.check(not public.casa_is_sysadmin(), 'Family is not admin');
select test.check((select family_id = 3 and second_family_id is null and role = 'family' and contact_email = 'familia@example.test'
  from public.profiles where id = auth.uid()), 'Family assignment persists without altering credentials or role');
select test.check((select count(*) = 1 from storage.objects), 'Family can read shared QR and cannot read receipts');
select test.expect_error($q$select public.casa_admin_rename_family(1, 'Hack')$q$, '42501');
select test.expect_error($q$select public.casa_admin_assign_user_families(auth.uid(), 1, null)$q$, '42501');
select test.expect_error($q$update public.profiles set family_id = 1 where id = auth.uid()$q$, '42501');
select test.expect_error($q$insert into storage.objects (bucket_id, name) values ('payment-qr', 'qr/hack.png')$q$, '42501');
update storage.objects set name = 'qr/hack.png';
delete from storage.objects;
select test.check((select count(*) = 1 and min(name) = 'qr/updated.png' from storage.objects), 'Family cannot modify or delete QR');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000003', false);
select test.check((select family_id = 2 and second_family_id = 3 from public.profiles where id = auth.uid()), 'Payer has distinct persisted families');
select test.expect_error($q$select public.casa_admin_rename_family(1, 'Hack')$q$, '42501');
select test.expect_error($q$select public.casa_admin_assign_user_families(auth.uid(), 1, 2)$q$, '42501');
select test.expect_error($q$insert into storage.objects (bucket_id, name) values ('payment-qr', 'qr/hack.png')$q$, '42501');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000004', false);
select test.expect_error($q$select public.casa_admin_rename_family(1, 'Hack')$q$, '42501');
select test.expect_error($q$select public.casa_admin_assign_user_families(auth.uid(), 1, null)$q$, '42501');
select test.expect_error($q$insert into storage.objects (bucket_id, name) values ('payment-qr', 'qr/hack.png')$q$, '42501');
select set_config('request.jwt.claim.sub', '', false);
select test.check(not public.casa_is_sysadmin(), 'No session is not admin');
select test.expect_error($q$select public.casa_admin_rename_family(1, 'Hack')$q$, '42501');
reset role;
set role anon;
select test.expect_error($q$select public.casa_is_sysadmin()$q$, '42501');
select test.expect_error($q$select public.casa_admin_rename_family(1, 'Hack')$q$, '42501');
select test.expect_error($q$select public.casa_admin_assign_user_families(null, 1, null)$q$, '42501');
select test.check((select count(*) = 0 from storage.objects), 'Anonymous cannot read private objects');
reset role;
select test.check((select family_id = 1 and amount = 123.45 from public.payments where id = 1), 'Existing payment stays with original family');
select test.check((select name = 'Familia García' from public.families where id = 1), 'Failed writes did not alter name');
select test.check((select family_id = 2 and second_family_id = 3 from public.profiles where role = 'payer'), 'Failed writes did not alter payer');
select test.check((select count(*) = 1 from storage.objects where bucket_id = 'receipts'), 'Receipt unchanged');
select json_build_object('backendChecks', count(*), 'result', 'PASS', 'database', 'isolated PostgreSQL') from test.results;
